<?php
if(PHP_SAPI !== 'cli'){http_response_code(404);exit;}
define('ROOT',dirname(__DIR__, 2).'/');define('LIB',ROOT.'lib/');define('VENDOR',ROOT.'vendor/');
$_SERVER['DOCUMENT_ROOT']='/';$_SERVER['REQUEST_TIME']=time();$_SERVER['HTTP_HOST']='localhost';$_SERVER['REQUEST_URI']='/';$_SESSION=[];
spl_autoload_register(function($class){foreach([LIB.$class.'.class.php',LIB.'session/'.$class.'.class.php'] as $file)if(is_file($file)){require_once $file;return;}});
require_once VENDOR.'autoload.php';require_once LIB.'function.php';
set_error_handler(function($severity,$message,$file,$line){if(error_reporting()&$severity)throw new ErrorException($message,0,$severity,$file,$line);});
$scratch=sys_get_temp_dir().'/mystep-utility-'.bin2hex(random_bytes(6));mkdir($scratch,0700);
$passed=$failed=0;
function same($expected,$actual){if($expected!==$actual)throw new RuntimeException('Expected '.var_export($expected,true).' got '.var_export($actual,true));}
function check($condition){if(!$condition)throw new RuntimeException('Assertion failed');}
function test($name,$run){global $passed,$failed;try{$run();$passed++;echo 'PASS '.$name.PHP_EOL;}catch(Throwable $e){$failed++;echo 'FAIL '.$name.': '.$e->getMessage().PHP_EOL;}}
function directory($name){global $scratch;$path=$scratch.'/'.$name;if(!is_dir($path))mkdir($path,0700,true);return $path.'/';}
try{
test('BOM handling preserves ordinary and binary prefixes',function(){foreach(['EXAMPLE','BEEF','\\XEF',"\xEF\xBBtext",'0',"\0\xff"] as $s)same($s,myFile::removeBom($s));same('value',myFile::removeBom("\xef\xbb\xbfvalue"));});
test('gzip and plain data round trip',function(){same('BEEF',myFile::gzdecode(gzencode('BEEF')));same('BEEF',myFile::gzdecode('BEEF'));});
test('file object string and explicit empty save',function(){ $p=directory('files').'data';file_put_contents($p,'EXAMPLE');$file=new myFile($p);same('EXAMPLE',(string)$file);same(7,$file->size);same(0,$file->save(''));same('',file_get_contents($p));$file->save('0');same('0',file_get_contents($p));});
test('file sizes support decimals and bare bytes',function(){same(1572864.0,myFile::getByte('1.5M'));same(100.0,myFile::getByte('100'));same(0,myFile::getByte('bad'));});
test('deleting a symlink leaves its target untouched',function(){ $target=directory('target');file_put_contents($target.'safe','keep');$link=directory('links').'external';symlink($target,$link);check(myFile::del($link));same('keep',file_get_contents($target.'safe'));});
test('recursive listing terminates at directory symlinks',function(){ $dir=directory('list');file_put_contents($dir.'a.txt','a');symlink($dir,$dir.'loop');$files=myFile::find('*.txt',$dir,true,myFile::FILE);same(1,count($files));same([],myFile::find('*',$dir.'missing'));});
test('copy refuses source descendants and reports success',function(){ $dir=directory('copy');file_put_contents($dir.'data.txt','data');same(false,myFile::copy($dir,$dir.'child/'));$out=directory('copy-out');same(true,myFile::copy($dir.'data.txt',$out));same('data',file_get_contents($out.'data.txt'));});
test('binary hex keeps leading zero nibbles',function(){$s="\x00\x01\x0a\xff";same('00010aff',myString::toHex($s));same($s,myString::fromHex(myString::toHex($s)));same(false,myString::fromHex('abc'));same(false,myString::fromHex('zz'));});
test('JSON preserves quotes booleans numbers and null',function(){ $data=['text'=>'a"b\\c','yes'=>true,'no'=>false,'int'=>3,'nil'=>null,'unicode'=>'中国'];same($data,myString::fromJson(myString::toJson($data)));same(false,myString::fromJson(myString::toJson(false)));same('value',myString::fromJson(myString::toJson('value')));});
test('INI string and file parsing preserve raw values',function(){ $text="[test]\nflag=true\nvalue=0012\n";$file=directory('ini').'data.ini';file_put_contents($file,$text);same(myString::fromIni($file),myString::fromIni($text));});
test('charset conversion keeps non-string scalar types',function(){same([true,false,1,null],myString::setCharset([true,false,1,null]));});
test('PHP configuration export preserves scalar and key types',function(){ $data=['number'=>'0012','word'=>'true','nil'=>null,'no'=>false,'key'=>['01'=>'007']];$path=directory('export').'data.php';file_put_contents($path,'<?php '.myString::toScript($data,'fixture').' return $fixture;');same($data,include $path);});
test('UTF-8 splitting includes emoji newline and ASCII',function(){same(['A','中','😀',"\n"],myString::breakStr("A中😀\n"));same('中😀',myString::substr('A中😀B',1,2,true));same('cd',myString::substr('abcdef',2,2));same('中',myString::substr('A中B',1,3));});
test('string object casts and encoding state',function(){ $s=new myString('Hello');same('Hello',(string)$s);$s->set('世界');same('世界',(string)$s);});
test('XML handles closing CDATA and invalid element keys',function(){ $xml=myString::toXML(['value'=>']]><x>&','bad key'=>'hello'],'item','root');$doc=simplexml_load_string($xml);same(']]><x>&',(string)$doc->value);same('hello',(string)$doc->item);});
test('request environment zero and explicit raw arrays',function(){putenv('MYSTEP_UTILITY_ENV=environment');same('environment',myReq::server('MYSTEP_UTILITY_ENV'));$_GET=['0'=>'zero','x'=>'<x>'];same('zero',myReq::get('0'));same($_GET,myReq::get('','!'));$_SERVER['ZERO_VALUE']='0';same('0',myReq::server('ZERO_VALUE'));putenv('MYSTEP_UTILITY_ENV');});
test('host port and IPv6 remain intact',function(){$_SERVER['HTTP_HOST']='[::1]:8443';same('[::1]:8443',myReq::server('HTTP_HOST'));$_SERVER['HTTP_HOST']='localhost';});
test('forwarded identity requires a trusted peer',function(){$_SERVER['REMOTE_ADDR']='2001:db8::1';$_SERVER['HTTP_X_FORWARDED_FOR']='198.51.100.1';$_SERVER['HTTP_X_FORWARDED_PROTO']='https';same('2001:db8::1',myReq::ip());same(false,isHttps());myReq::setTrustedProxies(['2001:db8::1']);same('198.51.100.1',myReq::ip());same(true,isHttps());myReq::setTrustedProxies([]);unset($_SERVER['HTTP_X_FORWARDED_FOR'],$_SERVER['HTTP_X_FORWARDED_PROTO']);});
test('session decoder rejects malformed lengths and nesting',function(){foreach(['x|s:999:"a";','x|a:1:{','x|R:bad;','x|','missing delimiter'] as $s)same(false,myReq::sessionDecode($s));same(['n'=>3,'s'=>'a|b'],myReq::sessionDecode('n|i:3;s|s:3:"a|b";'));});
class UtilityWakeup{public static $calls=0;public function __wakeup(){self::$calls++;}}
test('session display decoder never constructs untrusted classes by default',function(){ $data=myReq::sessionDecode('o|'.serialize(new UtilityWakeup()));same(0,UtilityWakeup::$calls);check(is_object($data['o']));});
test('minifier keeps fresh cache and expires old cache',function(){ $path=directory('minify').'out.js';$m=new myMinify('js',$path);$m->add('var cached = 1;')->get();same(true,$m->check(10));touch($path,time()-20);clearstatcache(true,$path);same(false,$m->check(10));$m->add('var x = 1;');check(strpos($m->get(),'var x=1')!==false);});
test('uncached minifier does not resolve empty path to directory',function(){ $m=new myMinify('css');$m->add('body { color: red; }');check(is_string($m->get()));});
class UtilityConstructor{public static $calls=0;public $value=null;public function __construct($value){self::$calls++;$this->value=$value;}}
class UtilityProxy extends myProxy{}
test('proxy runs required constructor exactly once',function(){ $p=new UtilityProxy('UtilityConstructor','value');same(1,UtilityConstructor::$calls);same('value',$p->value);$p->value=null;same(null,$p->value);});
test('reflection handles extensions interfaces and abstract classes',function(){ $ext=new myReflection('json');same('extension',$ext->type);same('json',$ext->getName());check(is_string($ext->export()));$i=new myReflection('Countable');same('interface',$i->type);$a=new myReflection('myBase');same('abstract',$a->type);check(is_array($a->getFunc()));});
test('reflection invokes functions with original parameters',function(){ $r=new myReflection('strlen');same(3,$r->get('abc'));same('strlen',$r->getName());});
test('evaluation preserves caller buffer and cleans up on throw',function(){ob_start();echo 'before';same('inside',myEval('echo "inside";'));same('before',ob_get_contents());try{myEval('throw new RuntimeException("fixture");');}catch(RuntimeException $e){}same('before',ob_get_contents());ob_end_clean();same(4,myEval('2+2',true));});
test('public helpers accept missing path and callable recursion',function(){same('https://example.test/',shortUrl('https://example.test'));same([2,[3]],recursionFunction(function($n){return $n+1;},[1,[2]]));$v=['a'=>1,'b'=>false];same(false,checkPara($v));});
test('exception handler preserves Throwable metadata',function(){ $old=[myException::$callback,myException::$callback_type,myException::$log_file,myException::$exit_on_error];myException::$callback=function(){};myException::$callback_type=0;myException::$log_file='';myException::$exit_on_error=false;try{ $e=new RuntimeException('fixture');myException::exceptionHandle($e);same($e->getMessage(),myException::$err_last['Info']);same($e->getLine(),myException::$err_last['Line']);}finally{[myException::$callback,myException::$callback_type,myException::$log_file,myException::$exit_on_error]=$old;myException::clear();}});
test('exception HTML escapes attacker-controlled fields',function(){myException::$display_details=true;myException::$err_last=['Type'=>'warning','Info'=>'<script>alert(1)</script>','URL'=>'"<x>'];$exit=myException::$exit_on_error;myException::$exit_on_error=false;ob_start();myException::show();$body=ob_get_clean();myException::$exit_on_error=$exit;myException::clear();myException::$display_details=false;check(strpos($body,'<script>alert(1)</script>')===false);check(strpos($body,'&lt;script&gt;')!==false);});
test('production exception response hides code and request details',function(){myException::$display_details=false;myException::$err_last=['Type'=>'error','Info'=>'secret-value'];ob_start();myException::show();$body=ob_get_clean();same('Internal server error',$body);myException::clear();});
test('archive destination rejects traversal absolute and symlink paths',function(){ $out=directory('safe-root');$outside=directory('outside');symlink($outside,$out.'link');foreach(['../escape','/abs','C:/abs','a\\b','link/file'] as $name)same(false,myFile::extractionPath($out,$name));same(rtrim(realpath($out),'/').'/a/b',myFile::extractionPath($out,'a/b'));});
test('packer round trip preserves BOM binary tails and empty files',function(){ $in=directory('pack-in');$out=directory('pack-out');$bin="\xef\xbb\xbfEXAMPLE\0tailfil";file_put_contents($in.'one.bin',$bin);file_put_contents($in.'empty','');$pkg=directory('packages').'one.pkg';$p=new myPacker($in,$pkg);check($p->pack());$p=new myPacker($out,$pkg);check($p->unpack(false));same($bin,file_get_contents($out.'one.bin'));same('',file_get_contents($out.'empty'));check(is_file($pkg));});
test('packer file additions accumulate',function(){ $in=directory('pack-list');file_put_contents($in.'a','a');file_put_contents($in.'b','b');$pkg=directory('packages').'list.pkg';$p=new myPacker($in,$pkg);$p->addFile($in.'a');$p->addFile($in.'b');check($p->pack());$out=directory('pack-list-out');check((new myPacker($out,$pkg))->unpack());check(is_file($out.'a') && is_file($out.'b'));});
test('packer rejects traversal before writing any entries',function(){ $out=directory('pack-bad');$pkg=directory('packages').'bad.pkg';$raw="file|good|4|0\nsafe"."file|../escaped|3|0\nbad";file_put_contents($pkg,gzcompress($raw));same(false,(new myPacker($out,$pkg))->unpack());check(!file_exists($out.'good'));check(is_file($pkg));});
test('packer rejects truncated and non-package input without destroying it',function(){ $pkg=directory('packages').'broken.pkg';foreach(['not-zlib',gzcompress("file|x|999|0\na")] as $bytes){file_put_contents($pkg,$bytes);same(false,(new myPacker(directory('broken-out'),$pkg))->unpack());same($bytes,file_get_contents($pkg));}});
test('archive expansion limits reject oversized output',function(){ $pkg=directory('packages').'limited.pkg';file_put_contents($pkg,gzcompress("file|a|5|0\n12345"));$p=new myPacker(directory('limit-out'),$pkg);$p->setLimits(4,10);same(false,$p->unpack());$file=directory('zip').'limited.zip';$z=new ZipArchive();$z->open($file,ZipArchive::CREATE);$z->addFromString('a','12345');$z->close();$z=new myZip($file);$z->setLimits(4,10);same(false,$z->unzip(directory('limit-zip')));});
test('zip reports invalid open as failure',function(){same(false,(new myZip(directory('zip').'missing.zip'))->unzip(directory('zip-out')));});
test('zip round trip includes hidden files',function(){ $in=directory('zip-in');file_put_contents($in.'a.txt','EXAMPLE');file_put_contents($in.'.hidden','hidden');$zip=directory('zip').'ok.zip';check((new myZip($zip,$in))->zip($in));$out=directory('zip-good');check((new myZip($zip))->unzip($out));same('EXAMPLE',file_get_contents($out.'a.txt'));same('hidden',file_get_contents($out.'.hidden'));});
test('failed zip creation preserves an existing output archive',function(){ $path=directory('zip').'existing.zip';file_put_contents($path,'old-bytes');$z=new myZip($path);same(false,$z->zip(directory('zip').'missing-input'));same('old-bytes',file_get_contents($path));});
test('zip rejects traversal and symlink members',function(){foreach(['../escaped','C:/escaped'] as $name){$file=directory('zip').md5($name).'.zip';$z=new ZipArchive();$z->open($file,ZipArchive::CREATE);$z->addFromString($name,'bad');$z->close();same(false,(new myZip($file))->unzip(directory('zip-bad')));} $file=directory('zip').'link.zip';$z=new ZipArchive();$z->open($file,ZipArchive::CREATE);$z->addFromString('link','../elsewhere');$z->setExternalAttributesName('link',ZipArchive::OPSYS_UNIX,0120777<<16);$z->close();same(false,(new myZip($file))->unzip(directory('zip-bad')));});
test('legacy encryption retains binary round trip',function(){ $plain="\0EXAMPLE\xff";same($plain,myEncrypt::decStr(myEncrypt::encStr($plain,'key'),'key'));same(false,myEncrypt::decStr('odd','key'));});
test('legacy encrypted files preserve originals on incorrect keys',function(){ $path=directory('crypto').'data';$plain=str_repeat('test',700);file_put_contents($path,$plain);check(myEncrypt::encFile($path,'key'));$encrypted=file_get_contents($path);same(false,myEncrypt::decFile($path,'wrong'));same($encrypted,file_get_contents($path));check(myEncrypt::decFile($path,'key'));same($plain,file_get_contents($path));});
test('authenticated envelopes reject tampering wrong keys and truncation',function(){ $key=random_bytes(32);$sealed=myEncrypt::seal("\0secret",$key);same("\0secret",myEncrypt::open($sealed,$key));same(false,myEncrypt::open($sealed,'wrong'));$bytes=base64_decode(substr($sealed,7));$bytes[44]=chr(ord($bytes[44])^1);same(false,myEncrypt::open('MSENC1:'.base64_encode($bytes),$key));same(false,myEncrypt::open(substr($sealed,0,-4),$key));same('',myEncrypt::open(myEncrypt::seal('',$key),$key));});
test('image crop updates own canvas and preserves external image ownership',function(){ $i=new myImg(20,10);same($i,$i->crop([0,0],5,4));same([5,4],$i->getSize());$external=imagecreatetruecolor(8,8);$crop=$i->crop([0,0],2,3,$external);same([2,3],$i->getSize($crop));same([5,4],$i->getSize());imagedestroy($external);imagedestroy($crop);$i->destroy();});
test('thumbnail remains usable after temporary canvas destruction',function(){ $i=new myImg(20,10);$out=directory('images').'thumb.png';$i->thumb(8,8,$out);same([8,8],$i->getSize());check($i->check());$i->make('png',directory('images').'again.png');$i->destroy();});
test('image resize preserves transparency and rejects zero scale',function(){ $i=new myImg(4,4);same(false,$i->resize(0));$i->resize(0.1);same([1,1],$i->getSize());$color=$i->getColor([0,0],false);same(127,$color['alpha']);$i->destroy();});
test('zero-total pie data does not divide by zero',function(){ $i=new myImg(20,20);same($i,$i->drawPie([0,0],[10,10],10,10));$i->destroy();});
test('GIF metadata reads the palette without byte offsets outside the header',function(){ $path=directory('images').'palette.gif';$image=imagecreate(3,2);imagecolorallocate($image,255,0,0);imagegif($image,$path);imagedestroy($image);$info=(new myImg())->gif_info($path);same(3,$info['width']);same(2,$info['height']);file_put_contents($path,'GIF');same(false,(new myImg())->gif_info($path));});
test('coordinate grid refuses non-progressing ticks and empty grouped bars',function(){ $image=new coordinateMaker(40,40);$image->setPara(['distance_x'=>1,'scale_x'=>0]);try{$image->buileCoordinate();throw new RuntimeException('accepted zero ticks');}catch(InvalidArgumentException $expected){}same($image,$image->drawBar([],[]));$image->destroy();});
test('mail sender validation accepts plus addressing and long TLD',function(){ $m=new myEmail();check($m->setFrom('hello+tag@example.technology'));$property=new ReflectionProperty('myEmail','from');$property->setAccessible(true);same('hello+tag@example.technology',$property->getValue($m));same(false,$m->setFrom("x@example.test\r\nBcc: y@example.test"));});
test('mail MIME attachments use correct argument order and complete boundaries',function(){ $path=directory('mail').'file.txt';file_put_contents($path,'EXAMPLE');$m=new myEmail('a@example.test');$m->setContent('<p>Hello</p>',true,'Hello alternate');check($m->addFile($path,'note.txt',false,'text/plain'));$mime=$m->buildMail();check(strpos($mime,'Content-Disposition: attachment;')!==false);check(strpos($mime,'Content-Type: text/plain;')!==false);check(strpos($mime,base64_encode('Hello alternate'))!==false);same($mime,$m->buildMail());});
